'use strict';

var STORAGE_KEY = 'todos-vanillajs';

var TodoModel = function () {
  this.todos = this.load();
};

TodoModel.prototype.load = function () {
  var data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

TodoModel.prototype.save = function () {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
};

TodoModel.prototype.findAll = function () {
  return this.todos;
};

TodoModel.prototype.findById = function (id) {
  return this.todos.find(function (t) { return t.id === id; });
};

TodoModel.prototype.add = function (title) {
  var todo = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    title: title,
    completed: false
  };
  this.todos.push(todo);
  this.save();
  return todo;
};

TodoModel.prototype.update = function (id, data) {
  var todo = this.findById(id);
  if (!todo) return;
  for (var key in data) {
    if (data.hasOwnProperty(key)) {
      todo[key] = data[key];
    }
  }
  this.save();
};

TodoModel.prototype.remove = function (id) {
  this.todos = this.todos.filter(function (t) { return t.id !== id; });
  this.save();
};

TodoModel.prototype.removeCompleted = function () {
  this.todos = this.todos.filter(function (t) { return !t.completed; });
  this.save();
};

TodoModel.prototype.toggleAll = function (checked) {
  this.todos.forEach(function (t) { t.completed = checked; });
  this.save();
};

TodoModel.prototype.allCompleted = function () {
  return this.todos.length > 0 && this.todos.every(function (t) { return t.completed; });
};

TodoModel.prototype.activeCount = function () {
  return this.todos.filter(function (t) { return !t.completed; }).length;
};

TodoModel.prototype.completedCount = function () {
  return this.todos.filter(function (t) { return t.completed; }).length;
};

'use strict';

var ENTER_KEY = 13;
var ESCAPE_KEY = 27;

var TodoController = function (model) {
  this.model = model;
  this.filter = 'all';
  this.$todoList = document.querySelector('.todo-list');
  this.$main = document.querySelector('.main');
  this.$footer = document.querySelector('.footer');
  this.$toggleAll = document.querySelector('#toggle-all');
  this.$todoCount = document.querySelector('.todo-count');
  this.$clearCompleted = document.querySelector('.clear-completed');
  this.$newTodo = document.querySelector('.new-todo');
  this.$filters = document.querySelectorAll('.filters a');

  this.loadFilter();
  this.bindEvents();
  this.render();
};

TodoController.prototype.loadFilter = function () {
  var hash = window.location.hash.replace('#/', '') || 'all';
  if (hash !== 'all' && hash !== 'active' && hash !== 'completed') hash = 'all';
  this.filter = hash;
};

TodoController.prototype.bindEvents = function () {
  var self = this;

  this.$newTodo.addEventListener('keyup', function (e) {
    if (e.keyCode !== ENTER_KEY) return;
    var title = self.$newTodo.value.trim();
    if (title === '') return;
    self.model.add(title);
    self.$newTodo.value = '';
    self.render();
  });

  this.$toggleAll.addEventListener('change', function () {
    self.model.toggleAll(self.$toggleAll.checked);
    self.render();
  });

  this.$clearCompleted.addEventListener('click', function () {
    self.model.removeCompleted();
    self.render();
  });

  this.$todoList.addEventListener('click', function (e) {
    var target = e.target;
    var $li = target.closest('li');
    if (!$li) return;
    var id = $li.dataset.id;

    if (target.classList.contains('toggle')) {
      var todo = self.model.findById(id);
      if (todo) {
        self.model.update(id, { completed: !todo.completed });
        self.render();
      }
    }

    if (target.classList.contains('destroy')) {
      self.model.remove(id);
      self.render();
    }
  });

  this.$todoList.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName !== 'LABEL') return;
    var $li = target.closest('li');
    if (!$li) return;
    $li.classList.add('editing');
    var $editInput = $li.querySelector('.edit');
    $editInput.value = $editInput.value || target.textContent;
    $editInput.focus();
  });

  this.$todoList.addEventListener('keyup', function (e) {
    if (e.keyCode !== ENTER_KEY && e.keyCode !== ESCAPE_KEY) return;
    var $li = e.target.closest('li');
    if (!$li) return;
    var $editInput = $li.querySelector('.edit');
    if (e.keyCode === ESCAPE_KEY) {
      $li.classList.remove('editing');
      $editInput.value = $li.querySelector('label').textContent;
      return;
    }
    var title = $editInput.value.trim();
    if (title === '') {
      self.model.remove($li.dataset.id);
    } else {
      self.model.update($li.dataset.id, { title: title });
    }
    $li.classList.remove('editing');
    self.render();
  });

  this.$todoList.addEventListener('focusout', function (e) {
    var $editInput = e.target;
    if (!$editInput.classList.contains('edit')) return;
    var $li = $editInput.closest('li');
    if (!$li) return;
    if ($li.classList.contains('editing')) {
      var title = $editInput.value.trim();
      if (title === '') {
        self.model.remove($li.dataset.id);
      } else {
        self.model.update($li.dataset.id, { title: title });
      }
      $li.classList.remove('editing');
      self.render();
    }
  });

  window.addEventListener('hashchange', function () {
    self.loadFilter();
    self.render();
  });
};

TodoController.prototype.getFilteredTodos = function () {
  var todos = this.model.findAll();
  var self = this;
  return todos.filter(function (t) {
    if (self.filter === 'active') return !t.completed;
    if (self.filter === 'completed') return t.completed;
    return true;
  });
};

TodoController.prototype.render = function () {
  var todos = this.model.findAll();
  var filteredTodos = this.getFilteredTodos();
  var activeCount = this.model.activeCount();
  var completedCount = this.model.completedCount();

  this.$main.style.display = todos.length > 0 ? 'block' : 'none';
  this.$footer.style.display = todos.length > 0 ? 'block' : 'none';

  this.$toggleAll.checked = this.model.allCompleted();

  var html = '';
  filteredTodos.forEach(function (todo) {
    var liClass = '';
    if (todo.completed) liClass += 'completed';
    html += '<li data-id="' + todo.id + '" class="' + liClass + '">';
    html += '<div class="view">';
    html += '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>';
    html += '<label>' + TodoController.escapeHtml(todo.title) + '</label>';
    html += '<button class="destroy"></button>';
    html += '</div>';
    html += '<input class="edit" value="' + TodoController.escapeHtml(todo.title) + '">';
    html += '</li>';
  });
  this.$todoList.innerHTML = html;

  this.$todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

  this.$clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

  this.$filters.forEach(function (a) {
    a.classList.remove('selected');
    var href = a.getAttribute('href');
    var filterName = href.replace('#/', '') || 'all';
    if (filterName === self.filter) a.classList.add('selected');
  });
};

TodoController.escapeHtml = function (text) {
  var div = document.createElement('div');
  div.appendChild(document.createTextNode(text));
  return div.innerHTML;
};

