    if (title === '') {
      self.model.remove($li.dataset.id);
    } else {
      self.model.update($li.dataset.id, { title: title });
    }
    $li.classList.remove('editing');
    self.render();
  });

  this.$todoList.addEventListener('focusout', function (e) {
    var $editInput = e.target;
    if (!$editInput.classList.contains('edit')) return;
    var $li = $editInput.closest('li');
    if (!$li) return;
    if ($li.classList.contains('editing')) {
      var title = $editInput.value.trim();
      if (title === '') {
        self.model.remove($li.dataset.id);
      } else {
        self.model.update($li.dataset.id, { title: title });
      }
      $li.classList.remove('editing');
      self.render();
    }
  });

  window.addEventListener('hashchange', function () {
    self.loadFilter();
    self.render();
  });
};

TodoController.prototype.getFilteredTodos = function () {
  var todos = this.model.findAll();
  var self = this;
  return todos.filter(function (t) {
    if (self.filter === 'active') return !t.completed;
    if (self.filter === 'completed') return t.completed;
    return true;
  });
};

TodoController.prototype.render = function () {
  var self = this;
  var todos = this.model.findAll();
  var filteredTodos = this.getFilteredTodos();
  var activeCount = this.model.activeCount();
  var completedCount = this.model.completedCount();

  this.$main.style.display = todos.length > 0 ? 'block' : 'none';
  this.$footer.style.display = todos.length > 0 ? 'block' : 'none';

  this.$toggleAll.checked = this.model.allCompleted();

  var html = '';
  filteredTodos.forEach(function (todo) {
    var liClass = '';
    if (todo.completed) liClass += 'completed';
    html += '<li data-id="' + todo.id + '" class="' + liClass + '">';
    html += '<div class="view">';
    html += '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>';
    html += '<label>' + TodoController.escapeHtml(todo.title) + '</label>';
    html += '<button class="destroy"></button>';
    html += '</div>';
    html += '<input class="edit" value="' + TodoController.escapeHtml(todo.title) + '">';
    html += '</li>';
  });
  this.$todoList.innerHTML = html;

  this.$todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

  this.$clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

  this.$filters.forEach(function (a) {
    a.classList.remove('selected');
    var href = a.getAttribute('href');
    var filterName = href.replace('#/', '') || 'all';
    if (filterName === self.filter) a.classList.add('selected');
  });
};

TodoController.escapeHtml = function (text) {
  var div = document.createElement('div');
  div.appendChild(document.createTextNode(text));
  return div.innerHTML;
};

